50: // NewScorer builds a scorer from the exact instruction terms to watch for.
51: func NewScorer(terms []string) *Scorer {
52: 	copied := make([]string, 0, len(terms))
53: 	for _, term := range terms {
54: 		copied = append(copied, strings.ToLower(term))
55: 	}
56: 	return &Scorer{terms: copied}
57: }
