59: // LoadTerms extracts all instruction terms from an AIL rule file.
60: func LoadTerms(path string) ([]string, error) {
61: 	data, err := os.ReadFile(path)
62: 	if err != nil {
63: 		return nil, err
64: 	}
65: 	parsed := parser.Parse(string(data), path)
66: 	ir := interpreter.Interpret(parsed).IR
67: 	terms := make([]string, 0)
68: 	for _, rule := range ir.Rules {
69: 		for _, group := range [][]string{rule.Do, rule.Never, rule.Verify, rule.Fallback} {
70: 			terms = append(terms, group...)
71: 		}
72: 	}
73: 	return terms, nil
74: }
